#include "h2_g99_loader_ui.h"

#include "hal/h2_pal_display.h"
#include "os/h2_pal_mem.h"
#include "os/h2_pal_sync.h"
#include "h2_g99_art.h"
#include "h2_g99_brand.h"
#include "h2_lvgl_platform.h"
#include "include/lvgl/font/lv_tiny_ttf.h"
#include "lvgl.h"

#include <string.h>

/* Generated by the font_subset target: printable ASCII of the system font. */
extern const uint8_t h2_g99_loader_font_data[];
extern const size_t h2_g99_loader_font_size;

typedef struct image {
  uint8_t* pixels;
  lv_image_dsc_t dsc;
} image_t;

struct h2_g99_loader_ui {
  h2_runtime_t* runtime;
  h2_pal_mutex_t* mutex;
  h2_g99_loader_state_t state;
  h2_g99_brand_layout_t layout;
  bool display_open;
  bool lvgl_ready;
  lv_display_t* display;
  uint8_t* render_buffer;
  size_t render_bytes;
  lv_font_t* font;
  image_t icon;
  image_t mark;
  lv_obj_t* status;
  lv_obj_t* track;
  lv_obj_t* fill;
  h2_pal_result_t flush_result;
};

static void display_flush(lv_display_t* display, const lv_area_t* area,
                          uint8_t* pixels) {
  h2_g99_loader_ui_t* ui = lv_display_get_user_data(display);
  if (ui != NULL && area != NULL && pixels != NULL) {
    const h2_display_rect_t rect = {area->x1, area->y1, area->x2 - area->x1 + 1,
                                    area->y2 - area->y1 + 1};
    int rc = h2_pal_display_draw_bitmap(
        ui->runtime->display, &rect, pixels,
        lv_draw_buf_width_to_stride((uint32_t)rect.width,
                                    LV_COLOR_FORMAT_RGB565),
        H2_DISPLAY_PIXEL_RGB565);
    if (rc == H2_PAL_OK && lv_display_flush_is_last(display))
      rc = h2_pal_display_present(ui->runtime->display);
    if (rc != H2_PAL_OK && ui->flush_result == H2_PAL_OK)
      ui->flush_result = (h2_pal_result_t)rc;
  }
  lv_display_flush_ready(display);
}

/* The same ARGB8888 images Main draws on its boot first frame. */
static bool image_alloc(h2_g99_loader_ui_t* ui, image_t* img, int32_t w,
                        int32_t h) {
  const size_t size = (size_t)w * (size_t)h * 4u;
  img->pixels = h2_pal_mem_alloc(ui->runtime->mem, size);
  if (img->pixels == NULL) return false;
  memset(&img->dsc, 0, sizeof(img->dsc));
  img->dsc.header.magic = LV_IMAGE_HEADER_MAGIC;
  img->dsc.header.cf = LV_COLOR_FORMAT_ARGB8888;
  img->dsc.header.w = (uint32_t)w;
  img->dsc.header.h = (uint32_t)h;
  img->dsc.header.stride = (uint32_t)w * 4u;
  img->dsc.data_size = (uint32_t)size;
  img->dsc.data = img->pixels;
  return true;
}

static void image_free(h2_g99_loader_ui_t* ui, image_t* img) {
  if (img->pixels != NULL) h2_pal_mem_free(ui->runtime->mem, img->pixels);
  memset(img, 0, sizeof(*img));
}

static lv_obj_t* plain(lv_obj_t* parent, int32_t x, int32_t y, int32_t w,
                       int32_t h) {
  lv_obj_t* obj = lv_obj_create(parent);
  if (obj == NULL) return NULL;
  lv_obj_remove_style_all(obj);
  lv_obj_set_scrollable(obj, false);
  lv_obj_set_clickable(obj, false);
  lv_obj_set_pos(obj, x, y);
  lv_obj_set_size(obj, w, h);
  lv_obj_set_style_bg_opa(obj, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_radius(obj, 0, LV_PART_MAIN);
  return obj;
}

static lv_obj_t* brand_image(lv_obj_t* parent, const image_t* img, int32_t x,
                             int32_t y) {
  lv_obj_t* obj = lv_image_create(parent);
  if (obj == NULL) return NULL;
  lv_image_set_src(obj, &img->dsc);
  lv_obj_set_pos(obj, x, y);
  lv_obj_set_clickable(obj, false);
  return obj;
}

static void teardown(h2_g99_loader_ui_t* ui) {
  if (ui->lvgl_ready) {
    if (ui->display != NULL) lv_display_delete(ui->display);
    if (ui->font != NULL) lv_tiny_ttf_destroy(ui->font);
    lv_deinit();
    h2_lvgl_platform_deinit();
  }
  ui->display = NULL;
  ui->font = NULL;
  ui->lvgl_ready = false;
  if (ui->render_buffer != NULL)
    h2_pal_mem_free(ui->runtime->mem, ui->render_buffer);
  ui->render_buffer = NULL;
  image_free(ui, &ui->icon);
  image_free(ui, &ui->mark);
  if (ui->display_open) (void)h2_pal_display_close(ui->runtime->display);
  ui->display_open = false;
}

static h2_pal_result_t build(h2_g99_loader_ui_t* ui) {
  h2_runtime_t* runtime = ui->runtime;
  int rc = h2_pal_display_open(runtime->display);
  if (rc != H2_PAL_OK) return (h2_pal_result_t)rc;
  ui->display_open = true;
  /* GizPocket shows the Loader at full brightness, Main's default too. */
  (void)h2_pal_display_set_brightness_percent(runtime->display, 100u);
  h2_display_info_t info;
  memset(&info, 0, sizeof(info));
  rc = h2_pal_display_get_info(runtime->display, &info);
  if (rc != H2_PAL_OK) return (h2_pal_result_t)rc;
  const h2_g99_brand_layout_t* l = &ui->layout;
  if (!h2_g99_brand_layout((int32_t)info.width, (int32_t)info.height,
                           &ui->layout))
    return H2_PAL_ERR_UNSUPPORTED;
  if (!image_alloc(ui, &ui->icon, l->icon_image_w, l->icon_image_h) ||
      !h2_g99_art_brand_icon(ui->icon.pixels, l->icon_image_w,
                             l->icon_image_h) ||
      !image_alloc(ui, &ui->mark, l->wordmark_image_w, l->wordmark_image_h) ||
      !h2_g99_art_wordmark(ui->mark.pixels, l->cell, l->shadow))
    return H2_PAL_ERR_NO_MEMORY;
  const int32_t rows = l->height / 10 > 16 ? l->height / 10 : 16;
  ui->render_bytes = (size_t)l->width * (size_t)rows * 2u;
  ui->render_buffer = h2_pal_mem_alloc(runtime->mem, ui->render_bytes);
  if (ui->render_buffer == NULL) return H2_PAL_ERR_NO_MEMORY;
  const h2_lvgl_platform_config_t platform = {
      .allocator = runtime->mem,
      .task_api = runtime->task,
      .sync_api = runtime->sync,
      .queue_api = runtime->queue,
      .time_api = runtime->time,
  };
  if (h2_lvgl_platform_init(&platform) != 0) return H2_PAL_ERR_UNAVAILABLE;
  lv_init();
  ui->lvgl_ready = true;
  ui->font = lv_tiny_ttf_create_data_ex(h2_g99_loader_font_data,
                                        h2_g99_loader_font_size, l->status_font,
                                        LV_FONT_KERNING_NONE, 64u);
  ui->display = lv_display_create(l->width, l->height);
  if (ui->font == NULL || ui->display == NULL) return H2_PAL_ERR_NO_MEMORY;
  lv_display_set_user_data(ui->display, ui);
  lv_display_set_color_format(ui->display, LV_COLOR_FORMAT_RGB565);
  lv_display_set_flush_cb(ui->display, display_flush);
  lv_display_set_buffers(ui->display, ui->render_buffer, NULL,
                         (uint32_t)ui->render_bytes,
                         LV_DISPLAY_RENDER_MODE_PARTIAL);
  lv_obj_t* screen = lv_screen_active();
  lv_obj_set_scrollable(screen, false);
  lv_obj_set_style_bg_color(screen, lv_color_hex(0x000000u), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_t* icon = brand_image(screen, &ui->icon, l->icon_x, l->group_y);
  lv_obj_t* mark = brand_image(screen, &ui->mark, l->wordmark_x, l->wordmark_y);
  ui->status = lv_label_create(screen);
  ui->track = plain(screen, 0, l->bar_y, l->width, l->bar_h);
  ui->fill = plain(screen, 0, l->bar_y, 0, l->bar_h);
  if (icon == NULL || mark == NULL || ui->status == NULL || ui->track == NULL ||
      ui->fill == NULL)
    return H2_PAL_ERR_NO_MEMORY;
  lv_obj_set_style_bg_color(ui->track, lv_color_hex(H2_G99_COLOR_DEEP),
                            LV_PART_MAIN);
  lv_obj_set_style_text_font(ui->status, ui->font, LV_PART_MAIN);
  lv_label_set_long_mode(ui->status, LV_LABEL_LONG_MODE_DOTS);
  lv_obj_set_width(ui->status, l->width - 2 * l->status_x);
  /* Put the font's baseline on the layout's status baseline. */
  const int32_t above_baseline = ui->font->line_height - ui->font->base_line;
  lv_obj_set_pos(ui->status, l->status_x, l->status_baseline - above_baseline);
  return H2_PAL_OK;
}

static h2_pal_result_t redraw(h2_g99_loader_ui_t* ui) {
  h2_g99_loader_view_t view;
  h2_g99_loader_state_view(&ui->state, &view);
  const uint32_t tone = view.error ? H2_G99_COLOR_ERROR : H2_G99_COLOR_STATUS;
  lv_label_set_text(ui->status, view.status);
  lv_obj_set_style_text_color(ui->status, lv_color_hex(tone), LV_PART_MAIN);
  lv_obj_set_hidden(ui->status, !view.status_visible);
  const uint32_t percent = view.bar_percent > 100u ? 100u : view.bar_percent;
  /* round(W * percent / 100) */
  const int32_t fill_w =
      (int32_t)(((int64_t)ui->layout.width * percent * 2 + 100) / 200);
  lv_obj_set_width(ui->fill, fill_w);
  lv_obj_set_style_bg_color(
      ui->fill,
      lv_color_hex(view.error ? H2_G99_COLOR_ERROR : H2_G99_COLOR_PURPLE),
      LV_PART_MAIN);
  lv_obj_set_hidden(ui->track, !view.bar_visible);
  lv_obj_set_hidden(ui->fill, !view.bar_visible || fill_w == 0);
  ui->flush_result = H2_PAL_OK;
  lv_refr_now(ui->display);
  return ui->flush_result;
}

h2_pal_result_t h2_g99_loader_ui_open(h2_runtime_t* runtime,
                                      h2_g99_loader_ui_t** out_ui) {
  if (out_ui == NULL) return H2_PAL_ERR_INVALID_ARG;
  *out_ui = NULL;
  if (runtime == NULL || runtime->mem == NULL || runtime->sync == NULL ||
      runtime->display == NULL)
    return H2_PAL_ERR_INVALID_ARG;
  h2_g99_loader_ui_t* ui = h2_pal_mem_alloc(runtime->mem, sizeof(*ui));
  if (ui == NULL) return H2_PAL_ERR_NO_MEMORY;
  memset(ui, 0, sizeof(*ui));
  ui->runtime = runtime;
  h2_g99_loader_state_init(&ui->state);
  const h2_pal_mutex_config_t config = {"g99-loader-ui", runtime->mem, 0u};
  h2_pal_result_t rc = h2_pal_mutex_create(runtime->sync, &config, &ui->mutex);
  if (rc == H2_PAL_OK) rc = build(ui);
  if (rc == H2_PAL_OK) rc = redraw(ui);
  if (rc != H2_PAL_OK) {
    h2_g99_loader_ui_close(ui);
    return rc;
  }
  *out_ui = ui;
  return H2_PAL_OK;
}

void h2_g99_loader_ui_close(h2_g99_loader_ui_t* ui) {
  if (ui == NULL) return;
  teardown(ui);
  if (ui->mutex != NULL)
    (void)h2_pal_mutex_destroy(ui->runtime->sync, ui->mutex);
  h2_pal_mem_free(ui->runtime->mem, ui);
}

typedef enum event {
  EVENT_READY,
  EVENT_INSTALLING,
  EVENT_PROGRESS,
  EVENT_FAILED,
  EVENT_LAUNCHING,
} event_t;

static h2_pal_result_t update(h2_g99_loader_ui_t* ui, event_t event,
                              h2_loader_install_phase_t phase,
                              uint64_t completed, uint64_t total, int code) {
  if (ui == NULL) return H2_PAL_ERR_INVALID_ARG;
  h2_pal_result_t rc = h2_pal_mutex_lock(ui->runtime->sync, ui->mutex);
  if (rc != H2_PAL_OK) return rc;
  switch (event) {
    case EVENT_READY:
      h2_g99_loader_state_ready(&ui->state);
      break;
    case EVENT_INSTALLING:
      h2_g99_loader_state_installing(&ui->state);
      break;
    case EVENT_PROGRESS:
      h2_g99_loader_state_progress(&ui->state, phase, completed, total);
      break;
    case EVENT_FAILED:
      h2_g99_loader_state_failed(&ui->state, code);
      break;
    case EVENT_LAUNCHING:
      h2_g99_loader_state_launching(&ui->state);
      break;
  }
  rc = redraw(ui);
  const h2_pal_result_t unlocked =
      h2_pal_mutex_unlock(ui->runtime->sync, ui->mutex);
  return rc != H2_PAL_OK ? rc : unlocked;
}

h2_pal_result_t h2_g99_loader_ui_ready(h2_g99_loader_ui_t* ui) {
  return update(ui, EVENT_READY, 0, 0u, 0u, 0);
}

h2_pal_result_t h2_g99_loader_ui_installing(h2_g99_loader_ui_t* ui) {
  return update(ui, EVENT_INSTALLING, 0, 0u, 0u, 0);
}

h2_pal_result_t h2_g99_loader_ui_progress(h2_g99_loader_ui_t* ui,
                                          h2_loader_install_phase_t phase,
                                          uint64_t completed, uint64_t total) {
  return update(ui, EVENT_PROGRESS, phase, completed, total, 0);
}

h2_pal_result_t h2_g99_loader_ui_failed(h2_g99_loader_ui_t* ui, int code) {
  return update(ui, EVENT_FAILED, 0, 0u, 0u, code);
}

h2_pal_result_t h2_g99_loader_ui_launching(h2_g99_loader_ui_t* ui) {
  return update(ui, EVENT_LAUNCHING, 0, 0u, 0u, 0);
}

void h2_g99_loader_ui_state(h2_g99_loader_ui_t* ui,
                            h2_g99_loader_state_t* out) {
  if (out == NULL) return;
  h2_g99_loader_state_init(out);
  if (ui == NULL) return;
  if (h2_pal_mutex_lock(ui->runtime->sync, ui->mutex) != H2_PAL_OK) return;
  *out = ui->state;
  (void)h2_pal_mutex_unlock(ui->runtime->sync, ui->mutex);
}
